import{_ as e,o as t,c as o,a2 as n}from"./chunks/framework.DDY-poMm.js";const c=JSON.parse('{"title":"Install & Update","description":"","frontmatter":{},"headers":[],"relativePath":"app/install.md","filePath":"app/install.md","lastUpdated":1790683574000}'),s={name:"app/install.md"};function i(r,a,l,p,d,h){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="install-update" tabindex="-1">Install &amp; Update <a class="header-anchor" href="#install-update" aria-label="Permalink to &quot;Install &amp; Update&quot;">​</a></h1><h2 id="first-install" tabindex="-1">First install <a class="header-anchor" href="#first-install" aria-label="Permalink to &quot;First install&quot;">​</a></h2><ol><li>On the platform&#39;s website, open the <strong>Download Center</strong> and choose Android (or scan the QR code on the <a href="/CoinExchange/app/download">Download App</a> page)</li><li>Once the browser finishes downloading, tap the package</li><li>On first install, Android asks <strong>whether to allow installing apps from unknown sources</strong> — you must allow it to continue</li></ol><div class="tip custom-block"><p class="custom-block-title">Why this prompt appears</p><p>This is Android&#39;s standard protection for every install outside an app store, not something specific to this app. Once allowed, later updates won&#39;t ask again.</p></div><h2 id="automatic-updates" tabindex="-1">Automatic updates <a class="header-anchor" href="#automatic-updates" aria-label="Permalink to &quot;Automatic updates&quot;">​</a></h2><p>Since v1.0.2, the app checks for a new version every time it starts.</p><h3 id="when-a-new-version-is-available" tabindex="-1">When a new version is available <a class="header-anchor" href="#when-a-new-version-is-available" aria-label="Permalink to &quot;When a new version is available&quot;">​</a></h3><p>The app shows a prompt with the new version number and what changed.</p><ul><li>Tap <strong>&quot;Update now&quot;</strong>: the app shows download progress, then opens the system installer when done; confirm to finish updating</li><li>Tap <strong>&quot;Later&quot;</strong>: the prompt closes and won&#39;t bother you again that day; it reminds you once more the next day</li></ul><h3 id="will-updating-lose-my-data" tabindex="-1">Will updating lose my data? <a class="header-anchor" href="#will-updating-lose-my-data" aria-label="Permalink to &quot;Will updating lose my data?&quot;">​</a></h3><p><strong>No.</strong> Updates install over the existing app, keeping your login and local settings — no need to log in again.</p><h3 id="seeing-an-important-update-prompt" tabindex="-1">Seeing an &quot;Important update&quot; prompt <a class="header-anchor" href="#seeing-an-important-update-prompt" aria-label="Permalink to &quot;Seeing an &quot;Important update&quot; prompt&quot;">​</a></h3><p>If a version has a serious problem, the platform may mark it as requiring an update. In that case the update prompt <strong>cannot be closed</strong>, and you must update to keep using the app. This is rare and usually means the old version has an issue affecting your use or the safety of your assets.</p><h2 id="checking-your-version" tabindex="-1">Checking your version <a class="header-anchor" href="#checking-your-version" aria-label="Permalink to &quot;Checking your version&quot;">​</a></h2><p>Open the app → &quot;Me&quot; → scroll to the bottom to see the installed version, e.g. <code>v1.0.4</code>.</p><div class="tip custom-block"><p class="custom-block-title">When reporting a problem</p><p>Please tell support this version number. The same problem can behave completely differently across versions, and the version number greatly speeds up troubleshooting.</p></div><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>The download doesn&#39;t progress after tapping update?</strong> Check your network connection. The package is about 44 MB and can be slow on a weak connection. Close the prompt, connect to Wi-Fi, reopen the app and update again.</p><p><strong>The download finished, but no install screen appeared?</strong> Most likely the &quot;Install unknown apps&quot; permission was not granted. Find this app under &quot;Settings → Apps&quot; on your phone, enable the permission and try again.</p><p><strong>&quot;App not installed&quot;?</strong> If your phone has an app with the same name from a different source (e.g. an old package downloaded elsewhere), mismatched signatures prevent installing over it. Uninstall the old version first, then install.</p><div class="warning custom-block"><p class="custom-block-title">Uninstalling clears data</p><p>After reinstalling you will need to log in again. Make sure you remember your account and password, or check with support first.</p></div>',21)])])}const m=e(s,[["render",i]]);export{c as __pageData,m as default};
